const id = location.pathname.split('/d/')[1].split('/')[0];
async function getCsv(sheet){
  const res = await fetch(`https://docs.google.com/spreadsheets/d/${id}/gviz/tq?tqx=out:csv&sheet=${encodeURIComponent(sheet)}`, {credentials:'include'});
  return await res.text();
}
window.__csv2023 = await getCsv('2023');
window.__csv2024 = await getCsv('2024');
JSON.stringify({len2023: window.__csv2023.length, len2024: window.__csv2024.length});

function parseCSV(text){
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  for (let i = 0; i < text.length; i++){
    const c = text[i];
    if (inQuotes){
      if (c === '"'){
        if (text[i+1] === '"'){ field += '"'; i++; }
        else { inQuotes = false; }
      } else field += c;
    } else {
      if (c === '"') inQuotes = true;
      else if (c === ','){ row.push(field); field=''; }
      else if (c === '\n'){ row.push(field); rows.push(row); row=[]; field=''; }
      else if (c === '\r'){}
      else field += c;
    }
  }
  if (field.length || row.length){ row.push(field); rows.push(row); }
  return rows;
}
window.__parse2023 = parseCSV(window.__csv2023);
window.__parse2024 = parseCSV(window.__csv2024);
JSON.stringify({rows2023: window.__parse2023.length, rows2024: window.__parse2024.length, cols2023: window.__parse2023[0].length, cols2024: window.__parse2024[0].length});

const targets = ['costs','netto','brutto','model year','mileage','score','origin','no.','vat type','km','rok','najazd','stav','cena'];
const hits = [];
for (let r=0; r<Math.min(window.__parse2024.length, 10); r++){
  const row = window.__parse2024[r];
  for (let c=0; c<row.length; c++){
    const v = (row[c]||'').toString().toLowerCase();
    if (v && targets.some(t=>v.includes(t))){
      hits.push(`r${r}c${c}:${row[c]}`);
    }
  }
}
JSON.stringify(hits);

const targets = ['cost','netto','brutto','model','mileage','score','origin','vat','km','rok','najazd','stav','cena','vin','vek'];
const found = {};
for (const t of targets) found[t] = [];
for (let r=0; r<window.__parse2024.length; r++){
  const row = window.__parse2024[r];
  for (let c=0; c<row.length; c++){
    const v = (row[c]||'').toString().toLowerCase();
    for (const t of targets){
      if (v.includes(t) && found[t].length<5) found[t].push(`r${r}c${c}`);
    }
  }
}
JSON.stringify(found);

