function num(v){
  if (v===undefined || v===null) return null;
  let s = v.toString().trim();
  if (s==='' || s==='–' || s==='-') return null;
  s = s.replace(/[€%\s ]/g,'').replace(/\./g,'').replace(',', '.');
  // careful: remove thousand-dot only if pattern like 1.234,56 -- but Slovak uses space as thousands sep, not dot, for these fields. So dots shouldn't appear except maybe not at all.
  const f = parseFloat(s);
  return isNaN(f) ? null : f;
}
function pct(v){
  if (v===undefined || v===null) return null;
  let s = v.toString().trim();
  if (s==='' || s==='–' || s==='-' || s.includes('DIV')) return null;
  s = s.replace(/[%\s ]/g,'').replace(',', '.');
  const f = parseFloat(s);
  return isNaN(f) ? null : f/100;
}
function parseDate(v){
  if (!v) return null;
  const s = v.toString().trim();
  const m = s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);
  if (!m) return null;
  return {y:+m[3], mo:+m[2], d:+m[1], iso: `${m[3]}-${String(m[2]).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`};
}
