import json
with open('raw_rows.json') as f:
    rows = json.load(f)

def normModel(v):
    s = v.replace('Volkswagen','VW',1).strip() if v.startswith('Volkswagen') else v
    two = ['Alfa Romeo','Mercedes-Benz','Land Rover']
    for b in two:
        if s.startswith(b):
            parts = s.split()
            n = len(b.split())
            return b + ' ' + (parts[n] if len(parts)>n else '')
    parts = s.split()
    return ' '.join(parts[:2])

models = set()
for r in rows:
